guidance.correct_example:
from dataclasses import dataclass
from typing import TypeVar, Generic, Optional

class Result(Generic[T]):
    _is_success: bool
    value: Optional[T]
    message: str

    def is_success(self) -> bool:
        return self._is_success

    @staticmethod
    def success(value: T, message: str = 'Success') -> Result[T]:
        return Result(_is_success=True, value=value, message=message)

    @staticmethod
    def failure(message: str) -> Result[None]:
        return Result(_is_success=False, value=None, message=message)

